#!/usr/bin/env python3
"""Represent exact scalar augmentation as a causal-past volume moment of wave sources."""
import json,sys,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
src=json.loads((ROOT/'research/nima/results/nnmhv-kernel-wall-tail-boundary.json').read_text());K=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_matrix']]);K0=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_without_upper_boundary_transport']]);m=3;events=sorted(((i,j) for i in range(1,m+1) for j in range(i,m+1)),key=lambda x:(x[1]-x[0],x[0]));leq=lambda x,y:y[0]<=x[0] and x[1]<=y[1];Z=s.Matrix([[1 if leq(x,y) else 0 for y in events] for x in events]);Mu=Z.inv();f=s.Matrix([K[j-1,i-1] for i,j in events]);f0=s.Matrix([K0[j-1,i-1] for i,j in events]);g=Mu*f;g0=Mu*f0;vol=[sum(Z[:,k]) for k in range(len(events))];moment=s.factor(sum(vol[k]*g[k] for k in range(len(events))));moment0=s.factor(sum(vol[k]*g0[k] for k in range(len(events))));amp=s.factor(sum(f));amp0=s.factor(sum(f0));contrib=[{'interval':list(e),'length':e[1]-e[0]+1,'causal_past_volume':int(vol[k]),'expected_triangular_volume':(e[1]-e[0]+1)*(e[1]-e[0]+2)//2,'source':str(s.factor(g[k])),'scalar_contribution':str(s.factor(vol[k]*g[k]))} for k,e in enumerate(events)];checks={'column_volume_is_triangular_number':all(x['causal_past_volume']==x['expected_triangular_volume'] for x in contrib),'physical_scalar_is_source_volume_moment':moment==amp,'unupdated_scalar_is_source_volume_moment':moment0==amp0,'boundary_scalar_shift_is_simple_source_sum':s.factor((amp-amp0)-sum((g-g0)[k] for k,e in enumerate(events) if e[0]==e[1]))==0}
out={'schema':'marici.nima.nnmhv-scalar-causal-source-moment.v1','identity':'S=sum_I f(I)=sum_J Vol(past(J)) g(J)','volume':'Vol(past([i,j]))=L(L+1)/2, L=j-i+1','physical_scalar':str(amp),'source_contributions':contrib,'checks':{k:bool(v) for k,v in checks.items()},'passed':all(bool(v) for v in checks.values()),'meaning':'Scalar augmentation is the causal-past volume moment of the local Möbius source density. Primitive simple-root boundary sources have unit volume, so their total source charge equals the boundary-induced scalar shift.','bridges':['discrete Green-function source representation','causal-past volume weighting','global observable as source moment','triangular interval volumes','boundary charge equals scalar response']};p=ROOT/'research/nima/results/nnmhv-scalar-causal-source-moment.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
